import numpy as np,sys,itertools
from collections import defaultdict
f=sys.argv[1]
L=open(f).read().split('\n'); n=int(L[0])
s=[];p=[]
for l in L[2:2+n]:
    t=l.split(); s.append(t[0]); p.append([float(x) for x in t[1:4]])
p=np.array(p)
d=np.linalg.norm(p[:,None]-p[None],axis=-1); np.fill_diagonal(d,99)
cov={'H':0.31,'C':0.76,'Si':1.11,'Cu':1.32}
bonds=defaultdict(list)
for i,j in itertools.combinations(range(n),2):
    if d[i,j] < 1.3*(cov[s[i]]+cov[s[j]]):
        bonds[i].append(j); bonds[j].append(i)
# report Cu
for i in range(n):
    if s[i]=='Cu':
        print(i,'Cu nbrs',[(j,s[j],round(d[i,j],2)) for j in bonds[i]])
# allyl carbons: C bonded to Cu
print('--- C bonded to Cu')
for i in range(n):
    if s[i]=='C' and any(s[j]=='Cu' for j in bonds[i]):
        print(i,[(j,s[j]) for j in bonds[i]])
print('min nonbond', min(d[i,j] for i,j in itertools.combinations(range(n),2) if j not in bonds[i]))
# valence check
for i in range(n):
    nb=[j for j in bonds[i] if s[j]!='Cu']
    exp={'H':1,'C':4,'Si':4,'Cu':0}[s[i]]
    if s[i]!='Cu' and len(nb)!=exp and not (s[i]=='C' and len(nb)==3):
        print('VAL',i,s[i],len(nb),[(j,s[j]) for j in bonds[i]])
